// Routers.tsx
import { HashRouter, Switch, Route } from "react-router-dom";
import Coin from "./routers/Coin";
import Coins from "./routers/Coins";

// Switch -> 한 번에 하나의 Route 를 렌더링 할 수 있도록 함.
// * react-router-dom v6.0.0 부터 Switch -> Routes 변경됨. *
function Router() {
  return (
    <HashRouter>
      <Switch>
        <Route path="/:coinId">
          <Coin />
        </Route>
        <Route path="/">
          <Coins />
        </Route>
      </Switch>
    </HashRouter>
  );
}

export default Router;
