// Coins.tsx
import { Helmet } from "react-helmet";
import { useQuery } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { fetchCoins } from "../api";
import styled from "styled-components";
import { BiSun, BiSolidMoon, BiArrowBack } from "react-icons/bi";
import { useRecoilState } from "recoil";
import { themeModeAtom } from "../atoms";

const Container = styled.div`
  max-width: 100%;
  width: 30rem;
  padding: 2rem 1rem;
  margin: 0 auto;
`;
const Header = styled.header`
  height: 10vh;
  display: flex;
  justify-content: center;
  align-items: center;
`;
const CoinList = styled.ul``;
const Coin = styled.li`
  background-color: ${(props) => props.theme.boxBgColor};
  color: ${(props) => props.theme.boxTextColor};
  margin-bottom: 1rem;
  padding: 1rem;
  font-size: 11px;
  border-radius: 5px;git push origin --delete gh-pages
  cursor: pointer;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
  transition: all 0.25s ease-in-out;
  a {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }
  &:hover {
    box-shadow: rgba(0, 0, 0, 0.16) 0px 10px 36px 0px,
      rgba(0, 0, 0, 0.06) 0px 0px 0px 1px;
    color: ${(props) => props.theme.pointColor};
  }
`;
const Img = styled.img`
  width: 25px;
  height: 25px;
  border-radius: 50%;
  border: 1px solid ${(props) => props.theme.boxTextColor};
`;
const Title = styled.h1`
  font-size: 1.5rem;
  font-weight: bold;
  color: ${(props) => props.theme.pointColor};
`;
const Loader = styled.div`
  font-size: 0.85rem;
  text-align: center;
  opacity: 0.35;
`;
const ThemeButton = styled.button`
  position: fixed;
  left: 1rem;
  bottom: 1rem;
  font-size: 2rem;
  color: ${(props) => props.theme.pointColor};
  display: flex;
  align-items: center;
  justify-content: center;
  width: 35px;
  height: 35px;
  border-radius: 50%;
  background: ${(props) => props.theme.boxBgColor};
  font-size: 20px;
  border: 0;
  cursor: pointer;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
`;

interface ICoin {
  id: string;
  name: string;
  symbol: string;
  rank: number;
  is_new: boolean;
  is_active: boolean;
  type: string;
}

function Coins() {
  // useQuery 는 2개의 argument 를 필요로 한다.
  // 1. queryKey :쿼리의 고유 식별자
  // 2. queryFn : 데이터를 가져와서 return 해주는 함수 (= fetcher 함수) 를 넘겨주어야 함.
  // isLoading : fetcher 함수가 실행 중이면 true, 끝나면 false
  // data : fetcher 함수가 return 한 데이터를 담음
  const { data, isLoading } = useQuery<ICoin[]>({
    queryKey: ["coins"],
    queryFn: fetchCoins,
  });
  /* 
  const [coins, setCoins] = useState<ICoin[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    // ()();
    // (() => console.log())();
    (async () => {
      const response = await fetch("https://api.coinpaprika.com/v1/coins");
      const json = await response.json();
      // a.slice(0, 2) -> 첫 번째부터 두 번째까지 잘라냄
      setCoins(json.slice(0, 100));
      setLoading(false);
    })();
  }, []); 
  */

  // 토글 처리
  const [themeMode, setThemeMode] = useRecoilState(themeModeAtom);

  return (
    <Container>
      <Helmet>
        <title>Coins</title>
      </Helmet>
      <ThemeButton
        onClick={() =>
          setThemeMode((prev) => (prev === "light" ? "dark" : "light"))
        }
      >
        {themeMode === "light" ? <BiSun /> : <BiSolidMoon />}
      </ThemeButton>
      <Header>
        <Title>Coins</Title>
      </Header>
      {isLoading ? (
        <Loader>Loading ...</Loader>
      ) : (
        <CoinList>
          {data?.slice(0, 100).map((coin) => (
            <Coin key={coin.id}>
              {
                // Link
                // 1. string <Link to ="/">
                // 2. query argument <Link to ="/courses?sort=name">
                // 3. object 를 통해 데이터를 다른 화면으로 보낼 수 있다.
              }
              <Link
                to={{
                  pathname: `/${coin.id}`,
                  state: { name: coin.name },
                }}
              >
                <Img
                  src={`https://cryptoicon-api.pages.dev/icons/128/color/${coin.symbol.toLowerCase()}.png`}
                />
                {coin.name} &rarr;
              </Link>
            </Coin>
          ))}
        </CoinList>
      )}
    </Container>
  );
}

export default Coins;
