// Chart.tsx
import { fetchCoinHistory } from "../api";
import { useQuery } from "@tanstack/react-query";
import ApexChart from "react-apexcharts";

interface IHistorical {
  time_open: string;
  time_close: string;
  open: string;
  high: string;
  low: string;
  close: string;
  volume: string;
  market_cap: number;
}
interface CharProps {
  coinId: string;
}

function Chart({ coinId }: CharProps) {
  const { isLoading, data = [] } = useQuery<IHistorical[]>({
    queryKey: ["ohlcv", coinId],
    queryFn: () => fetchCoinHistory(coinId),
  });

  const candlestickData = data.map((price) => ({
    x: new Date(price.time_close),
    y: [
      parseFloat(Number(price.open).toFixed(3)),
      parseFloat(Number(price.high).toFixed(3)),
      parseFloat(Number(price.low).toFixed(3)),
      parseFloat(Number(price.close).toFixed(3)),
    ],
  }));
  return (
    <>
      {isLoading ? (
        "Loading chart..."
      ) : (
        <ApexChart
          type="candlestick"
          series={[
            {
              name: "Price",
              data: candlestickData,
            },
          ]}
          options={{
            theme: {
              mode: "dark",
            },
            chart: {
              height: 300,
              width: 500,
              toolbar: {
                show: false,
              },
              background: "transparent",
            },
            grid: { show: true },
            plotOptions: {
              candlestick: {
                colors: {
                  upward: "#0be881",
                  downward: "#ef5350",
                },
                wick: {
                  useFillColor: true,
                },
              },
            },
            xaxis: {
              type: "datetime",
              axisBorder: { show: false },
              axisTicks: { show: true },
              labels: { show: true },
            },
            yaxis: {
              show: false,
            },
            tooltip: {
              y: {
                formatter: (value) => `$${value.toFixed(2)}`,
              },
            },
          }}
        />
      )}
    </>
  );
}

export default Chart;
